  .featured-card:hover { box-shadow: 0 4px 28px rgba(0,0,0,0.1); }
  .featured-thumb {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    min-height: 280px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
